package main

import "log"

type Item struct {
	Price int
	Qty   int
}

func total(items []Item) int {
	subtotal := 0
	for _, it := range items {
		subtotal += it.Price * it.Qty
	}
	log.Printf("subtotal: %d", subtotal)
	if subtotal > 10000 {
		subtotal -= subtotal / 10
	}
	return subtotal
}

func settle(ledger map[string]int, id string, subtotal int) {
	ledger[id] += subtotal
	log.Printf("subtotal: %d", subtotal)
}

func main() {
	ledger := map[string]int{}
	settle(ledger, "a1", total([]Item{{5, 2}, {7, 1}}))
}

package main

import "log"

type Resolver struct {
	cache  map[string]string
	served int
}

func cost(names []string) int {
	served := 0
	for _, n := range names {
		served += len(n)
	}
	log.Printf("served %d", served)
	return served * 3
}

func (r *Resolver) Lookup(name string) string {
	r.served++
	return r.cache[name]
}

func (r *Resolver) Close() {
	served := r.served
	r.cache = nil
	log.Printf("served %d", served)
}

func main() {
	r := &Resolver{cache: map[string]string{"a": "1.1.1.1"}}
	r.Lookup("a")
	_ = cost([]string{"a", "bb"})
	r.Close()
}

package main

import "log"

type Vec struct {
	X, Y int
}

type Move struct {
	Player string
	To     Vec
}

func simulate(start Vec, steps int) Vec {
	pos := start
	for i := 0; i < steps; i++ {
		pos.X += i
		pos.Y -= 1
		log.Printf("moved to %+v", pos)
	}
	return pos
}

func apply(world map[string]Vec, m Move) {
	pos := m.To
	world[m.Player] = pos
	log.Printf("moved to %+v", pos)
}

func main() {
	world := map[string]Vec{}
	apply(world, Move{"ann", simulate(Vec{}, 3)})
}

package main

import (
	"log"
	"strings"
)

func words(line string) []string {
	parts := strings.Fields(line)
	if len(parts) > 3 {
		count := len(parts)
		log.Printf("count: %d", count)
		parts = parts[:3]
	}
	return parts
}

func migrate(rows []string, store map[int]string) {
	for i, r := range rows {
		store[i] = strings.TrimSpace(r)
	}
	count := len(store)
	log.Printf("count: %d", count)
}

func main() {
	store := map[int]string{}
	migrate(words("a b c d e"), store)
}

package main

import (
	"log"
	"time"
)

func scale(raw int) int {
	level := raw * 255 / 1023
	if level > 255 {
		level = 255
	}
	log.Printf("level %d", level)
	return level
}

func sample(tick <-chan time.Time, read func() int) {
	for range tick {
		level := read()
		log.Printf("level %d", level)
	}
}

func main() {
	t := time.NewTicker(time.Second)
	defer t.Stop()
	go sample(t.C, func() int { return scale(512) })
	time.Sleep(2 * time.Second)
}

