import (
	"log"
	"strings"
)

type Mailer struct {
	sent map[string][]string
}

func clean(rcpt string) string {
	if strings.HasPrefix(rcpt, "<") {
		rcpt = strings.Trim(rcpt, "<>")
		log.Printf("recipient %s", rcpt)
	}
	return strings.ToLower(rcpt)
}

func (m *Mailer) deliver(rcpt, body string) {
	m.sent[rcpt] = append(m.sent[rcpt], body)
	log.Printf("recipient %s", rcpt)
}

func main() {
	m := &Mailer{sent: map[string][]string{}}
	m.deliver(clean("<Bob@example.com>"), "hi")
}

package main

import (
	"log"
	"net"
	"strings"
)

func shard(addr string, n int) int {
	peer := strings.Split(addr, ":")[0]
	sum := 0
	for _, c := range peer {
		sum += int(c)
	}
	log.Printf("peer %s", peer)
	return sum % n
}

func serve(ln net.Listener) {
	for {
		c, err := ln.Accept()
		if err != nil {
			return
		}
		peer := c.RemoteAddr().String()
		log.Printf("peer %s", peer)
		c.Close()
	}
}

func main() {
	println(shard("10.0.0.1:80", 4))
}

package main

import (
	"log"
	"strconv"
)

func parseQty(s string) int {
	stock, _ := strconv.Atoi(s)
	log.Printf("stock %d", stock)
	return stock
}

func restock(shelf, lot map[string]int) {
	for k, v := range lot {
		shelf[k] += v
	}
	stock := 0
	for _, v := range shelf {
		stock += v
	}
	log.Printf("stock %d", stock)
}

func main() {
	shelf := map[string]int{"bolt": 4}
	restock(shelf, map[string]int{"bolt": parseQty("12")})
}

package main

import (
	"log"
	"net"
	"strconv"
)

func join(host string, port int) string {
	addr := host + ":" + strconv.Itoa(port)
	log.Printf("listening on %s", addr)
	return addr
}

func start(addr string) error {
	ln, err := net.Listen("tcp", addr)
	if err != nil {
		return err
	}
	defer ln.Close()
	log.Printf("listening on %s", addr)
	for {
		c, err := ln.Accept()
		if err != nil {
			return err
		}
		c.Close()
	}
}

func main() {
	log.Fatal(start(join("127.0.0.1", 8080)))
}

package main

import (
	"log"
	"net"
)

type Session struct {
	conn  net.Conn
	moves int
}

func play(board []int) int {
	moves := 0
	for _, sq := range board {
		if sq == 0 {
			moves++
			log.Printf("moves: %d", moves)
		}
	}
	return moves
}

func (s *Session) Close() {
	moves := s.moves
	s.conn.Close()
	log.Printf("moves: %d", moves)
}

func main() {
	a, b := net.Pipe()
	s := &Session{conn: a, moves: play([]int{0, 1, 0})}
	s.Close()
	b.Close()
}
